contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _am) public {
        // Fresh deployment: this contract's recorded balance is below MinSum (default 1 ether),
        // so the Collect conditions cannot hold.
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        require(balBefore < minSumBefore);

        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethAfter = address(c).balance;

        assert(!reverted && balAfter == balBefore && ethAfter == ethBefore);
    }

    receive() external payable {}
}

